package com.gregtechceu.gtceu.api.machine;

import com.gregtechceu.gtceu.api.GTValues;
import com.gregtechceu.gtceu.api.blockentity.BlockEntityCreationInfo;
import com.gregtechceu.gtceu.api.capability.recipe.*;
import com.gregtechceu.gtceu.api.machine.feature.*;
import com.gregtechceu.gtceu.api.machine.trait.notifiable.*;
import com.gregtechceu.gtceu.api.machine.trait.recipe.IRecipeHandlerTrait;
import com.gregtechceu.gtceu.api.machine.trait.recipe.RecipeHandlerList;
import com.gregtechceu.gtceu.api.machine.trait.recipe.RecipeLogic;
import com.gregtechceu.gtceu.api.recipe.GTRecipeType;
import com.gregtechceu.gtceu.api.sync_system.annotations.SaveField;
import com.gregtechceu.gtceu.api.sync_system.annotations.SyncToClient;
import com.gregtechceu.gtceu.common.machine.trait.CleanroomReceiverTrait;
import com.gregtechceu.gtceu.utils.GTUtil;
import com.gregtechceu.gtceu.utils.ISubscription;

import it.unimi.dsi.fastutil.ints.Int2IntFunction;
import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.*;

/**
 * A tiered energy machine with recipe logic and item/fluid IO.
 */
public abstract class WorkableTieredMachine extends TieredEnergyMachine implements IRecipeLogicMachine,
                                            IMufflableMachine, IOverclockMachine {

    @Getter
    @SaveField
    @SyncToClient
    public final RecipeLogic recipeLogic;
    @Getter
    public final GTRecipeType[] recipeTypes;
    @Getter
    @Setter
    @SaveField
    public int activeRecipeType;
    @Getter
    protected final CleanroomReceiverTrait cleanroomReceiver;
    @SaveField
    public final NotifiableItemStackHandler importItems, exportItems;
    @SaveField
    public final NotifiableFluidTank importFluids, exportFluids;
    @SaveField
    public final NotifiableComputationContainer importComputation, exportComputation;
    @Getter
    protected final Map<IO, List<RecipeHandlerList>> capabilitiesProxy;
    @Getter
    protected final Map<IO, Map<RecipeCapability<?>, List<IRecipeHandler<?>>>> capabilitiesFlat;
    @SaveField
    @Getter
    protected int overclockTier;
    protected final List<ISubscription> traitSubscriptions;
    @SaveField
    @SyncToClient
    @Getter
    protected boolean isMuffled;
    protected boolean previouslyMuffled = true;

    /**
     * Creates a {@link WorkableTieredMachine}.
     * 
     * @param info                {@link BlockEntityCreationInfo}
     * @param tier                Machine tier.
     * @param recipeLogic         The recipe logic to use.
     * @param importSlots         The amount of item input slots this machine should have (can be 0).
     * @param exportSlots         The amount of item output slots this machine should have (can be 0).
     * @param fluidImportSlots    The amount of fluid input slots this machine should have (can be 0).
     * @param fluidExportSlots    The amount of fluid output slots this machine should have (can be 0).
     * @param energyEmitter       If this machine should input or output energy.
     * @param tankScalingFunction The tank scaling function which determines the capaacity of fluid slots.
     */
    public WorkableTieredMachine(BlockEntityCreationInfo info, int tier,
                                 RecipeLogic recipeLogic, int importSlots,
                                 int exportSlots,
                                 int fluidImportSlots, int fluidExportSlots, boolean energyEmitter,
                                 Int2IntFunction tankScalingFunction) {
        super(info, tier, (energyEmitter ?
                RecipeAmperageEnergyContainer.emitterContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1) :
                RecipeAmperageEnergyContainer.receiverContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1)));
        this.overclockTier = getMaxOverclockTier();
        this.recipeTypes = getDefinition().getRecipeTypes();
        this.activeRecipeType = 0;
        this.capabilitiesProxy = new EnumMap<>(IO.class);
        this.capabilitiesFlat = new EnumMap<>(IO.class);
        this.traitSubscriptions = new ArrayList<>();
        this.cleanroomReceiver = attachTrait(new CleanroomReceiverTrait());
        this.recipeLogic = attachTrait(recipeLogic);
        this.recipeLogic.setKeepSubscribing(false);
        this.importItems = attachTrait(new NotifiableItemStackHandler(importSlots, IO.IN));
        this.exportItems = attachTrait(new NotifiableItemStackHandler(exportSlots, IO.OUT));
        this.importFluids = attachTrait(
                new NotifiableFluidTank(fluidImportSlots, tankScalingFunction.applyAsInt(getTier()),
                        IO.IN));
        this.exportFluids = attachTrait(
                new NotifiableFluidTank(fluidExportSlots, tankScalingFunction.applyAsInt(getTier()),
                        IO.OUT));
        this.importComputation = attachTrait(new NotifiableComputationContainer(IO.IN, true));
        this.exportComputation = attachTrait(new NotifiableComputationContainer(IO.OUT, false));
    }

    /**
     * Creates a {@link WorkableTieredMachine} with default settings.<br>
     * The amount of item and fluid input and output slots is determined by the machine's recipe type.
     *
     * @param info                {@link BlockEntityCreationInfo}
     * @param tier                Machine tier.
     * @param energyEmitter       If this machine should input or output energy.
     * @param recipeLogic         The recipe logic to use.
     * @param tankScalingFunction The tank scaling function which determines the capaacity of fluid slots.
     */
    public WorkableTieredMachine(BlockEntityCreationInfo info, int tier, boolean energyEmitter, RecipeLogic recipeLogic,
                                 Int2IntFunction tankScalingFunction) {
        super(info, tier, (energyEmitter ?
                RecipeAmperageEnergyContainer.emitterContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1) :
                RecipeAmperageEnergyContainer.receiverContainer(GTValues.V[tier] * 64L, GTValues.V[tier], 1)));
        this.overclockTier = getMaxOverclockTier();
        this.recipeTypes = getDefinition().getRecipeTypes();
        this.activeRecipeType = 0;
        this.capabilitiesProxy = new EnumMap<>(IO.class);
        this.capabilitiesFlat = new EnumMap<>(IO.class);
        this.traitSubscriptions = new ArrayList<>();
        this.cleanroomReceiver = attachTrait(new CleanroomReceiverTrait());
        this.recipeLogic = attachTrait(recipeLogic);
        this.recipeLogic.setKeepSubscribing(false);
        this.importItems = attachTrait(
                new NotifiableItemStackHandler(getDefinition().getInputSize(ItemRecipeCapability.CAP, getRecipeTypes()),
                        IO.IN));
        this.exportItems = attachTrait(
                new NotifiableItemStackHandler(
                        getDefinition().getOutputSize(ItemRecipeCapability.CAP, getRecipeTypes()),
                        IO.OUT));
        this.importFluids = attachTrait(
                new NotifiableFluidTank(getDefinition().getInputSize(FluidRecipeCapability.CAP, getRecipeTypes()),
                        tankScalingFunction.applyAsInt(getTier()), IO.IN));
        this.exportFluids = attachTrait(
                new NotifiableFluidTank(getDefinition().getOutputSize(FluidRecipeCapability.CAP, getRecipeTypes()),
                        tankScalingFunction.applyAsInt(getTier()), IO.OUT));
        this.importComputation = attachTrait(new NotifiableComputationContainer(IO.IN, true));
        this.exportComputation = attachTrait(new NotifiableComputationContainer(IO.OUT, false));
    }

    /**
     * Creates a {@link WorkableTieredMachine} with default settings.<br>
     * The amount of item and fluid input and output slots is determined by the machine's recipe type.
     *
     * @param info                {@link BlockEntityCreationInfo}
     * @param tier                Machine tier.
     * @param energyEmitter       If this machine should input or output energy.
     * @param tankScalingFunction The tank scaling function which determines the capaacity of fluid slots.
     */
    public WorkableTieredMachine(BlockEntityCreationInfo info, int tier, boolean energyEmitter,
                                 Int2IntFunction tankScalingFunction) {
        this(info, tier, energyEmitter, new RecipeLogic(), tankScalingFunction);
    }

    //////////////////////////////////////
    // ***** Initialization ******//
    //////////////////////////////////////

    @Override
    public void onLoad() {
        super.onLoad();
        // attach self traits
        Map<IO, List<IRecipeHandler<?>>> ioTraits = new EnumMap<>(IO.class);

        for (var trait : getTraitHolder().getTraitsByInterface(IRecipeHandlerTrait.class)) {
            ioTraits.computeIfAbsent(trait.getHandlerIO(), i -> new ArrayList<>()).add(trait);
        }

        for (var entry : ioTraits.entrySet()) {
            var handlerList = RecipeHandlerList.of(entry.getKey(), entry.getValue());
            this.addHandlerList(handlerList);
            traitSubscriptions.add(handlerList.subscribe(recipeLogic::updateTickSubscription));
        }
    }

    @Override
    public void onUnload() {
        super.onUnload();
        traitSubscriptions.forEach(ISubscription::unsubscribe);
        traitSubscriptions.clear();
        capabilitiesProxy.clear();
        capabilitiesFlat.clear();
    }

    //////////////////////////////////////
    // ********** MISC ***********//
    //////////////////////////////////////

    public void setMuffled(boolean muffled) {
        isMuffled = muffled;
        syncDataHolder.markClientSyncFieldDirty("isMuffled");
    }

    //////////////////////////////////////
    // ******** OVERCLOCK *********//
    //////////////////////////////////////

    @Override
    public int getMaxOverclockTier() {
        return GTUtil.getTierByVoltage(Math.max(energyContainer.getInputVoltage(), energyContainer.getOutputVoltage()));
    }

    @Override
    public int getMinOverclockTier() {
        return 0;
    }

    @Override
    public void setOverclockTier(int tier) {
        if (!isRemote() && tier >= getMinOverclockTier() && tier <= getMaxOverclockTier()) {
            this.overclockTier = tier;
            this.recipeLogic.markLastRecipeDirty();
        }
    }

    @Override
    public long getOverclockVoltage() {
        return Math.min(GTValues.V[getOverclockTier()],
                Math.max(energyContainer.getInputVoltage(), energyContainer.getOutputVoltage()));
    }

    //////////////////////////////////////
    // ****** RECIPE LOGIC *******//
    //////////////////////////////////////

    @Override
    public void clientTick() {
        super.clientTick();
        if (previouslyMuffled != isMuffled) {
            previouslyMuffled = isMuffled;

            recipeLogic.updateSound();
        }
    }

    public GTRecipeType getRecipeType() {
        int index = activeRecipeType >= 0 && activeRecipeType < recipeTypes.length ? activeRecipeType : 0;
        return recipeTypes[index];
    }

    /**
     * Sets a recipe type of the machine.
     * FOR INTERNAL / TESTING USE ONLY!
     * NOT SUPPORTED FOR PRODUCTION USE!
     *
     * @param newType The new recipe type
     */
    @ApiStatus.Internal
    @VisibleForTesting
    public void setRecipeType(GTRecipeType newType) {
        recipeTypes[activeRecipeType] = newType;
    }
}

package com.gregtechceu.gtceu.api.machine.trait;

import com.gregtechceu.gtceu.api.machine.MetaMachine;
import com.gregtechceu.gtceu.api.machine.TickableSubscription;
import com.gregtechceu.gtceu.api.machine.multiblock.MultiblockControllerMachine;
import com.gregtechceu.gtceu.api.machine.trait.notifiable.NotifiableItemStackHandler;
import com.gregtechceu.gtceu.api.sync_system.SyncDataHolder;
import com.gregtechceu.gtceu.api.sync_system.managed.ISyncManaged;
import com.gregtechceu.gtceu.client.model.machine.MachineRenderState;
import com.gregtechceu.gtceu.common.machine.trait.AutoOutputTrait;
import com.gregtechceu.gtceu.common.machine.trait.CleanroomProviderTrait;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;

import lombok.Getter;
import lombok.Setter;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.Nullable;

import java.util.List;
import java.util.function.Predicate;

/**
 * A machine trait represents a generic capability or behaviour that is attached to a machine. <br>
 * <br>
 * For example, machine traits may provide a recipe handler that can handle specific inputs/outputs of a recipe (e.g.
 * {@link NotifiableItemStackHandler} for items). <br>
 * Machine traits can also attach additional behaviours to a machine (e.g. {@link AutoOutputTrait},
 * {@link CleanroomProviderTrait}) <br>
 * <br>
 * If a machine trait implements a capability interface, the trait will be returned by {@link MetaMachine#getCapability}
 * if the machine trait's capability validator prediate is true for that side.
 */
public abstract class MachineTrait implements ISyncManaged {

    @Getter
    protected final SyncDataHolder syncDataHolder = new SyncDataHolder(this);

    private @Nullable MetaMachine machine;
    @Setter
    protected Predicate<@Nullable Direction> capabilityValidator = $ -> true;

    @Getter
    @Setter(onMethod_ = @ApiStatus.Internal)
    private @Nullable String traitName;
    /**
     * The trait's callback priority. Traits with a higher priority will have their events fired
     * first, which may prevent traits with a lower priority from handling some events.
     */
    @Getter
    @Setter
    private int traitPriority = 1;

    public MachineTrait() {}

    public MetaMachine getMachine() {
        if (machine == null) throw new IllegalStateException(
                "Machine trait not attached to machine. Trait initialisation that depends on machine instance should run in onTraitAttached.");
        return machine;
    }

    @Override
    public @Nullable ISyncManaged getParentSyncObject() {
        return getMachine();
    }

    /**
     * A list containing the machine classes which this trait can be attached to.
     * If this trait is being attached to a machine class that does not conform to any of the list elements, an
     * exception is thrown.
     * If this list is empty, the trait can be attached to any machine.
     */
    protected List<Class<?>> validMachineClasses() {
        return List.of();
    }

    @ApiStatus.Internal
    public void setMachine(MetaMachine machine) {
        if (this.machine != null) throw new IllegalStateException("Machine trait already attached to a machine.");
        if (!validMachineClasses().isEmpty() &&
                validMachineClasses().stream().noneMatch(cls -> cls.isAssignableFrom(machine.getClass()))) {
            throw new IllegalArgumentException(
                    "Attempted to attach trait to invalid machine class %s".formatted(machine.getClass()));
        }
        this.machine = machine;
    }

    public @Nullable TickableSubscription subscribeServerTick(@Nullable TickableSubscription last, Runnable runnable) {
        return getMachine().subscribeServerTick(last, runnable);
    }

    public void unsubscribe(@Nullable TickableSubscription current) {
        getMachine().unsubscribe(current);
    }

    public BlockPos getBlockPos() {
        return getMachine().getBlockPos();
    }

    public Level getLevel() {
        return getMachine().getLevel();
    }

    public boolean isRemote() {
        return getMachine().isRemote();
    }

    public final boolean hasCapability(@Nullable Direction side) {
        return capabilityValidator.test(side);
    }

    @Override
    public void markAsChanged() {
        if (machine == null) return;
        getMachine().markAsChanged();
    }

    public MachineRenderState getRenderState() {
        return getMachine().getRenderState();
    }

    public void setRenderState(MachineRenderState state) {
        getMachine().setRenderState(state);
    }

    /**
     * Called when this trait is attached to a machine instance.
     */
    public void onTraitAttached() {}

    /**
     * Called when the machine is loaded. The entire world is not loaded when this method is called.
     * To schedule code to run on the first full world tick, do
     * {@code getMachine().scheduleForNextServerTick(callback)}
     */
    public void onMachineLoad() {}

    /**
     * Called when the machine is about to be unloaded.
     */
    public void onMachineUnload() {}

    /**
     * Called when the machine is destroyed.
     */
    public void onMachineDestroyed() {}

    /**
     * Called when the machine is attached to a controller<br>
     * Only called if this trait is attached to a multiblock part machine.
     *
     * @param controller The multiblock controller
     */
    public void addedToController(MultiblockControllerMachine controller) {}

    /**
     * Called when the machine is removed from a controller<br>
     * Only called if this trait is attached to a multiblock part machine.
     *
     * @param controller The multiblock controller
     */
    public void removedFromController(MultiblockControllerMachine controller) {}

    /**
     * Called when a neighboring block is updated.
     *
     * @param neighborBlock The neighbor block type.
     * @param neighborPos   The neighbor position.
     * @param isMoving      If the neighbor block is moving (e.g. moved by a piston)
     */
    public void onMachineNeighborChanged(Block neighborBlock, BlockPos neighborPos, boolean isMoving) {}
}

package com.gregtechceu.gtceu.api.machine.trait;

import com.gregtechceu.gtceu.GTCEu;
import com.gregtechceu.gtceu.api.machine.MetaMachine;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformer;
import com.gregtechceu.gtceu.api.sync_system.data_transformers.ValueTransformers;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;

import it.unimi.dsi.fastutil.objects.Object2ObjectOpenHashMap;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.Unmodifiable;
import org.jetbrains.annotations.UnmodifiableView;

import java.util.*;

public final class MachineTraitHolder {

    private final MetaMachine machine;

    private boolean allowTraitAttachment = true;

    private final List<MachineTrait> traits;

    private final Map<String, MachineTrait> traitsToSave;

    private @Nullable List<MachineTrait> allTraits = null;

    private final Map<Class<?>, List<MachineTrait>> traitsByClass;

    public MachineTraitHolder(MetaMachine machine) {
        this.machine = machine;
        this.traits = new ObjectArrayList<>();
        this.traitsByClass = new Object2ObjectOpenHashMap<>();
        this.traitsToSave = new Object2ObjectOpenHashMap<>();
    }

    /**
     * @return An unmodifiable list of all traits attached to this machine.
     */
    public @Unmodifiable List<MachineTrait> getAllTraits() {
        return allTraits != null ? allTraits : Collections.unmodifiableList(traits);
    }

    /**
     * Gets all traits implementing a specific interface/class
     */
    @SuppressWarnings("unchecked")
    public <T> @Unmodifiable List<T> getTraitsByInterface(Class<T> clazz) {
        if (traitsByClass.containsKey(clazz)) return (List<T>) traitsByClass.get(clazz);

        List<T> list = new ObjectArrayList<>();

        for (var t : getAllTraits()) {
            if (clazz.isAssignableFrom(t.getClass())) list.add(clazz.cast(t));
        }

        if (!allowTraitAttachment) traitsByClass.put(clazz, (List<MachineTrait>) Collections.unmodifiableList(list));
        return list;
    }

    /**
     * Attaches a trait to this machine, with the default trait callback priority of 1.
     * 
     * @param trait The trait to attach
     * @return The attached trait
     */
    public <T extends MachineTrait> T attachTrait(T trait) {
        return attachTrait(trait, 1);
    }

    /**
     * Attaches a trait to this machine. Traits must be attached before {@link MetaMachine#onLoad()}.
     * 
     * @param trait            The trait to attach
     * @param callbackPriority The trait's callback priority. Traits with a higher priority will have their events fired
     *                         first, which may prevent traits with a lower priority from handling some events.
     * @return The attached trait
     */
    public <T extends MachineTrait> T attachTrait(T trait, int callbackPriority) {
        if (!allowTraitAttachment)
            throw new IllegalStateException("Cannot add traits to machine after machine has been loaded.");

        trait.setTraitPriority(callbackPriority);

        addTraitToClassMap(trait.getClass(), trait);
        traits.add(trait);
        traits.sort(Comparator.comparingInt(MachineTrait::getTraitPriority).reversed());

        trait.setMachine(machine);
        trait.onTraitAttached();
        return trait;
    }

    @SuppressWarnings("unchecked")
    private void addTraitToClassMap(Class<? extends MachineTrait> clazz, MachineTrait trait) {
        var list = traitsByClass.computeIfAbsent(clazz, $ -> new ObjectArrayList<>(1));

        list.add(trait);
        list.sort(Comparator.comparingInt(MachineTrait::getTraitPriority).reversed());

        if (!clazz.getSuperclass().equals(MachineTrait.class))
            addTraitToClassMap((Class<? extends MachineTrait>) clazz.getSuperclass(), trait);
    }

    /**
     * Registers a trait with data to be saved or synced to the client.
     * Do not register a persistent trait and also store that trait as a syncable machine field, otherwise the trait
     * data will be duplicated. Use only one sync method.<br>
     * Note: Persistent traits must be attached before data load, or they will not be loaded correctly.
     *
     * @param traitName Unique identifier for this trait.
     * @param trait     The trait to register
     */
    public void attachPersistentTrait(String traitName, MachineTrait trait) {
        attachTrait(trait);
        registerPersistentTrait(traitName, trait);
    }

    /**
     * Registers a trait with data to be saved or synced to the client.
     * Do not register a persistent trait and also store that trait as a syncable machine field, otherwise the trait
     * data will be duplicated. Use only one sync method.<br>
     * Note: Persistent traits must be attached before data load, or they will not be loaded correctly.
     *
     * @param traitName        Unique identifier for this trait.
     * @param callbackPriority The trait's callback priority. Traits with a higher priority will have their events fired
     *                         first, which may prevent traits with a lower priority from handling some events.
     * @param trait            The trait to register
     */
    public void attachPersistentTrait(String traitName, MachineTrait trait, int callbackPriority) {
        attachTrait(trait, callbackPriority);
        registerPersistentTrait(traitName, trait);
    }

    /**
     * Registers a trait with data to be saved or synced to the client.
     * Do not register a persistent trait and also store that trait as a syncable machine field, otherwise the trait
     * data will be duplicated. Use only one sync method.
     *
     * @param traitName Unique identifier for this trait.
     * @param trait     The trait to register
     */
    public MachineTraitHolder registerPersistentTrait(String traitName, MachineTrait trait) {
        if (trait.getMachine() != machine) throw new IllegalArgumentException("Trait does not belong to this machine.");
        if (traitsToSave.containsKey(traitName))
            throw new IllegalArgumentException("Attempted to register duplicate trait save key \"" + traitName + "\"");
        trait.setTraitName(traitName);
        traitsToSave.put(traitName, trait);
        return this;
    }

    /**
     * Gets a trait registered by {@code registerPersistentTrait}
     * 
     * @param traitName the unique identifier for the trait
     * @return the trait, or null if not present
     */
    @SuppressWarnings("unchecked")
    public @Nullable <T extends MachineTrait> T getPersistentTrait(String traitName) {
        MachineTrait trait = traitsToSave.get(traitName);
        return trait == null ? null : (T) trait;
    }

    /**
     * Gets the first trait (trait with highest priority) with the specified class.
     * Also includes traits that are a subtype of the specified class.
     *
     * @param type The trait class to get
     * @return The trait, or null if no traits of the given type are present.
     */
    public <T extends MachineTrait> @Nullable T getTrait(Class<T> type) {
        List<MachineTrait> traitList = traitsByClass.get(type);
        if (traitList == null || traitList.isEmpty()) return null;
        return type.cast(traitList.get(0));
    }

    /**
     * Gets the first trait (trait with highest priority) with the specified class.
     * Also includes traits that are a subtype of the specified class.
     *
     * @param type The trait class to get
     * @return An optional result containing the trait if present.
     */
    public <T extends MachineTrait> Optional<T> getTraitOptional(Class<T> type) {
        return Optional.ofNullable(getTrait(type));
    }

    /**
     * Get all traits with the specified class.
     * Also includes traits that are a subtype of the specified class.
     * 
     * @return An unmodifiable list containing all traits of the specified class.
     */
    @SuppressWarnings("unchecked")
    public <T extends MachineTrait> @UnmodifiableView List<T> getTraits(Class<T> type) {
        List<T> traitList = (List<T>) traitsByClass.get(type);
        if (traitList == null) return List.of();
        return Collections.unmodifiableList(traitList);
    }

    public void machineLoaded() {
        allowTraitAttachment = false;

        // Cache traits so that repeated unmodifiableList calls aren't required.

        allTraits = Collections.unmodifiableList(traits);
    }

    private static class MachineTraitHolderTransformer implements ValueTransformer<MachineTraitHolder> {

        @Override
        public Tag serializeNBT(MachineTraitHolder value, TransformerContext<MachineTraitHolder> context) {
            CompoundTag tag = new CompoundTag();

            value.traitsToSave.forEach((k, v) -> tag.put(k, v.getSyncDataHolder().serializeNBT(context.lookup())));

            return tag;
        }

        @Override
        public @Nullable MachineTraitHolder deserializeNBT(Tag tag, TransformerContext<MachineTraitHolder> context) {
            var traitHolder = Objects.requireNonNull(context.currentValue());
            var compoundTag = (CompoundTag) tag;

            for (var key : compoundTag.getAllKeys()) {
                var trait = traitHolder.getPersistentTrait(key);
                if (trait == null) {
                    GTCEu.LOGGER.warn("Attempted to deserialise syncable trait '{}', but no syncable trait has that ID",
                            key);
                    continue;
                }

                trait.getSyncDataHolder().deserializeNBT(context.lookup(), compoundTag.getCompound(key));
            }

            return traitHolder;
        }

        @Override
        public void writeToPacket(FriendlyByteBuf buf, MachineTraitHolder value,
                                  TransformerContext<MachineTraitHolder> context) {
            buf.writeVarInt(value.traitsToSave.size());
            value.traitsToSave.forEach((name, trait) -> {
                buf.writeUtf(name);
                if (context.isClientFullSyncUpdate()) trait.getSyncDataHolder().resyncAllFields();
                trait.getSyncDataHolder().writeClientPacket(context.lookup(), buf);
            });
        }

        @Override
        public @Nullable MachineTraitHolder readFromPacket(FriendlyByteBuf buf,
                                                           TransformerContext<MachineTraitHolder> context) {
            var traitHolder = Objects.requireNonNull(context.currentValue());
            int length = buf.readVarInt();
            for (int i = 0; i < length; i++) {
                String name = buf.readUtf();

                var trait = traitHolder.getPersistentTrait(name);
                if (trait == null) {
                    throw new IllegalStateException(
                            "Reading packet data for syncable trait '%s', but no client-side syncable trait has that ID"
                                    .formatted(name));
                } else {
                    trait.getSyncDataHolder().readClientPacket(context.lookup(), buf);
                }
            }

            return traitHolder;
        }
    }

    static {
        ValueTransformers.registerTransformer(MachineTraitHolder.class, new MachineTraitHolderTransformer());
    }
}

package com.gregtechceu.gtceu.api.machine.trait.recipe;

